import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv3d_hw1_forward(torch::Tensor x,
                                  torch::Tensor weight,
                                  c10::optional<torch::Tensor> bias,
                                  int stride, int padding, int dilation, int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv2p1d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ Wt,
    const T* __restrict__ Bias,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win, int D,
    int Cout, int Cin_per_group, int Cout_per_group,
    int Kh, int Kw,
    int stride, int padding, int dilation,
    int groups,
    int Hout, int Wout, int Dout,
    int IH_TILE, int IW_TILE,
    int TILE_H, int TILE_W)
{
    extern __shared__ unsigned char smem_raw[];
    T* sX_ptr = reinterpret_cast<T*>(smem_raw);
    T* sW_ptr = sX_ptr + Cin_per_group * IH_TILE * IW_TILE;

    auto sX = make_tensor(make_smem_ptr(sX_ptr),
                           make_shape(Cin_per_group, IH_TILE, IW_TILE),
                           make_stride(IH_TILE * IW_TILE, IW_TILE, 1));
    auto sW = make_tensor(make_smem_ptr(sW_ptr),
                           make_shape(Cout_per_group, Cin_per_group, Kh, Kw),
                           make_stride(Cin_per_group * Kh * Kw, Kh * Kw, Kw, 1));

    int tx = threadIdx.x; // 0..TILE_W-1
    int ty = threadIdx.y; // 0..TILE_H-1
    int tid = ty * TILE_W + tx;
    int nthreads = TILE_W * TILE_H;

    int ow_base = blockIdx.x * TILE_W;
    int oh_base = blockIdx.y * TILE_H;

    int bz = blockIdx.z;
    int g = bz % groups;
    int tmp = bz / groups;
    int od = tmp % Dout;
    int n = tmp / Dout;

    int id = od * stride - padding; // kernel depth = 1

    int64_t Y_n_stride = (int64_t)Cout * Hout * Wout * Dout;
    auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * Y_n_stride),
                           make_shape(Cout, Hout, Wout, Dout),
                           make_stride((int64_t)Hout * Wout * Dout,
                                       (int64_t)Wout * Dout,
                                       (int64_t)Dout, (int64_t)1));

    int oh = oh_base + ty;
    int ow = ow_base + tx;

    if (id < 0 || id >= D) {
        if (oh < Hout && ow < Wout) {
            for (int oc = 0; oc < Cout_per_group; ++oc) {
                int oc_g = g * Cout_per_group + oc;
                T bval = (Bias != nullptr) ? Bias[oc_g] : T(0);
                mY(oc_g, oh, ow, od) = bval;
            }
        }
        return;
    }

    int64_t X_n_stride = (int64_t)Cin * H * Win * D;
    auto mX = make_tensor(make_gmem_ptr(X + (int64_t)n * X_n_stride),
                           make_shape(Cin, H, Win, D),
                           make_stride((int64_t)H * Win * D,
                                       (int64_t)Win * D,
                                       (int64_t)D, (int64_t)1));

    auto mW = make_tensor(make_gmem_ptr(Wt),
                           make_shape(Cout, Cin_per_group, Kh, Kw),
                           make_stride(Cin_per_group * Kh * Kw, Kh * Kw, Kw, 1));

    int ih_base = oh_base * stride - padding;
    int iw_base = ow_base * stride - padding;

    int total_in = Cin_per_group * IH_TILE * IW_TILE;
    for (int idx = tid; idx < total_in; idx += nthreads) {
        int c = idx / (IH_TILE * IW_TILE);
        int rem = idx % (IH_TILE * IW_TILE);
        int ihl = rem / IW_TILE;
        int iwl = rem % IW_TILE;
        int ih = ih_base + ihl;
        int iw = iw_base + iwl;
        T val = T(0);
        int c_global = g * Cin_per_group + c;
        if (ih >= 0 && ih < H && iw >= 0 && iw < Win) {
            val = mX(c_global, ih, iw, id);
        }
        sX(c, ihl, iwl) = val;
    }

    int total_w = Cout_per_group * Cin_per_group * Kh * Kw;
    for (int idx = tid; idx < total_w; idx += nthreads) {
        int oc = idx / (Cin_per_group * Kh * Kw);
        int rem = idx % (Cin_per_group * Kh * Kw);
        int c = rem / (Kh * Kw);
        int rem2 = rem % (Kh * Kw);
        int kh = rem2 / Kw;
        int kw = rem2 % Kw;
        int oc_g = g * Cout_per_group + oc;
        sW(oc, c, kh, kw) = mW(oc_g, c, kh, kw);
    }

    __syncthreads();

    if (oh < Hout && ow < Wout) {
        for (int oc = 0; oc < Cout_per_group; ++oc) {
            float acc = 0.0f;
            for (int c = 0; c < Cin_per_group; ++c) {
                for (int kh = 0; kh < Kh; ++kh) {
                    int ihl = ty * stride + kh * dilation;
                    for (int kw = 0; kw < Kw; ++kw) {
                        int iwl = tx * stride + kw * dilation;
                        float xval = (float)sX(c, ihl, iwl);
                        float wval = (float)sW(oc, c, kh, kw);
                        acc += xval * wval;
                    }
                }
            }
            int oc_g = g * Cout_per_group + oc;
            if (Bias != nullptr) acc += (float)Bias[oc_g];
            mY(oc_g, oh, ow, od) = static_cast<T>(acc);
        }
    }
}

torch::Tensor conv3d_hw1_forward(torch::Tensor x,
                                  torch::Tensor weight,
                                  c10::optional<torch::Tensor> bias,
                                  int stride, int padding, int dilation, int groups) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    if (bias.has_value()) TORCH_CHECK(bias.value().is_cuda(), "bias must be CUDA if provided");

    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    if (bias.has_value()) TORCH_CHECK(bias.value().scalar_type() == at::kFloat, "bias must be float32");

    TORCH_CHECK(x.dim() == 5, "x must be [N, C, H, W, D]");
    TORCH_CHECK(weight.dim() == 5, "weight must be [Cout, Cin/groups, Kh, Kw, 1]");
    TORCH_CHECK(weight.size(4) == 1, "weight last dim (kernel depth) must be 1");

    auto x_c = x.contiguous();
    auto w_c = weight.squeeze(4).contiguous(); // [Cout, Cin_per_group, Kh, Kw]

    int64_t N   = x_c.size(0);
    int64_t Cin = x_c.size(1);
    int64_t H   = x_c.size(2);
    int64_t Win = x_c.size(3);
    int64_t D   = x_c.size(4);

    int64_t Cout = w_c.size(0);
    int64_t Cin_per_group = w_c.size(1);
    int64_t Kh = w_c.size(2);
    int64_t Kw = w_c.size(3);

    TORCH_CHECK(Cin % groups == 0, "Cin must be divisible by groups");
    TORCH_CHECK(Cout % groups == 0, "Cout must be divisible by groups");
    TORCH_CHECK(Cin_per_group == Cin / groups, "weight in-channels mismatch");
    int64_t Cout_per_group = Cout / groups;

    TORCH_CHECK(stride > 0 && dilation > 0, "stride and dilation must be > 0");
    TORCH_CHECK(padding >= 0, "padding must be >= 0");

    int64_t Hout = (H + 2 * padding - dilation * (Kh - 1) - 1) / stride + 1;
    int64_t Wout = (Win + 2 * padding - dilation * (Kw - 1) - 1) / stride + 1;
    int64_t Dout = (D + 2 * padding - 1 * (1 - 1) - 1) / stride + 1; // kernel depth = 1
    TORCH_CHECK(Hout > 0 && Wout > 0 && Dout > 0, "Invalid output size computed");

    torch::Tensor b_c;
    const float* b_ptr = nullptr;
    if (bias.has_value()) {
        b_c = bias.value().contiguous();
        TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
        b_ptr = b_c.data_ptr<float>();
    }

    auto y = torch::empty({N, Cout, Hout, Wout, Dout}, x.options());

    constexpr int TILE_H = 16;
    constexpr int TILE_W = 16;

    int IH_TILE = (int)((TILE_H - 1) * stride + (Kh - 1) * dilation + 1);
    int IW_TILE = (int)((TILE_W - 1) * stride + (Kw - 1) * dilation + 1);

    size_t shared_bytes = (size_t)(Cin_per_group * IH_TILE * IW_TILE +
                                    Cout_per_group * Cin_per_group * Kh * Kw) * sizeof(float);

    dim3 block(TILE_W, TILE_H);
    dim3 grid(
        (unsigned)((Wout + TILE_W - 1) / TILE_W),
        (unsigned)((Hout + TILE_H - 1) / TILE_H),
        (unsigned)(N * Dout * groups)
    );

    cudaFuncSetAttribute(conv2p1d_kernel<float>,
                          cudaFuncAttributeMaxDynamicSharedMemorySize,
                          (int)shared_bytes);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    conv2p1d_kernel<float><<<grid, block, shared_bytes, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_ptr,
        y.data_ptr<float>(),
        (int)N, (int)Cin, (int)H, (int)Win, (int)D,
        (int)Cout, (int)Cin_per_group, (int)Cout_per_group,
        (int)Kh, (int)Kw,
        stride, padding, dilation,
        groups,
        (int)Hout, (int)Wout, (int)Dout,
        IH_TILE, IW_TILE,
        TILE_H, TILE_W
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "conv2p1d_kernel launch failed: ", cudaGetErrorString(err));

    return y;
}
"""

conv3d_ext = load_inline(
    name="cute_conv3d_hw1_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv3d_hw1_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    3D convolution with kernel (K, K, 1) implemented via a custom
    cooperative tiled CUDA/CuTe kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        assert in_channels % groups == 0
        assert out_channels % groups == 0

        # Weight shape matches nn.Conv3d: [Cout, Cin/groups, Kh, Kw, Kd=1]
        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels // groups, kernel_size, kernel_size, 1)
        )
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv3d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.weight.size(1) * self.weight.size(2) * self.weight.size(3) * self.weight.size(4)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv3d_hw1_forward(
            x.contiguous(),
            self.weight,
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.dilation),
            int(self.groups),
        )

